def inflate(raw):
    stream = io.BytesIO(raw)
    d = deflate.DeflateIO(stream, deflate.RAW, 9)
    data = d.read()
    d.close()
    return data

oled.fill(0)
oled.show()

while True:
    for encoded in FRAMES:
        raw = ubinascii.a2b_base64(encoded)
        data = inflate(raw)
        for i in range(len(data)):
            buf[i] ^= data[i]
        oled.blit(fb, 0, 0)
        oled.show()
        time.sleep_ms(100)


